import ast, re, sys, os
sys.path.insert(0, "/app/categorizationapp")
import categorizationapp.UtilityScripts.BankRegexConstants as BRC
import categorizationapp.UtilityScripts.RegexConstants as RC

consts = {}
for mod in (BRC, RC):
    for k, v in vars(mod).items():
        if isinstance(v, str):
            consts[k] = v

base = "/app/categorizationapp/categorizationapp"
files = []
for d in ("BankScripts", "UtilityScripts"):
    for f in sorted(os.listdir(os.path.join(base, d))):
        if f.endswith(".py"):
            files.append(os.path.join(base, d, f))

def pat_value(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Name) and node.id in consts:
        return consts[node.id]
    return None

for path in files:
    src = open(path).read()
    tree = ast.parse(src)
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "py_extract":
            patv, idxv = None, None
            args = list(node.args)
            # signature py_extract(description, pat, index)
            if len(args) >= 2: patv = pat_value(args[1])
            if len(args) >= 3 and isinstance(args[2], ast.Constant): idxv = args[2].value
            for kw in node.keywords:
                if kw.arg == "pat": patv = pat_value(kw.value)
                if kw.arg == "index" and isinstance(kw.value, ast.Constant): idxv = kw.value.value
            if patv is None or idxv is None:
                continue
            try:
                ngroups = re.compile(patv).groups
            except re.error as e:
                print(f"{path}:{node.lineno}: BAD REGEX {patv!r}: {e}")
                continue
            if idxv >= ngroups:
                print(f"{path}:{node.lineno}: index={idxv} but pattern has {ngroups} group(s): {patv!r}")
EOF

cd /tmp/opencode && python3 - <<'EOF'
import ast, os
base = "/app/categorizationapp/categorizationapp"
files = []
for d in ("BankScripts", "UtilityScripts"):
    for f in sorted(os.listdir(os.path.join(base, d))):
        if f.endswith(".py"):
            files.append(os.path.join(base, d, f))

for path in files:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        # find assignments: conditions_choices = [ ... ]
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.List):
            tgt = node.targets[0]
            if isinstance(tgt, ast.Name) and tgt.id == "conditions_choices":
                for row in node.value.elts:
                    if not isinstance(row, ast.List) or len(row.elts) != 2:
                        n = len(row.elts) if isinstance(row, ast.List) else "?"
                        print(f"{path}:{row.lineno}: row with {n} element(s)")
        # amount comparisons with strings
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr in ("isin","eq","lt","gt","le","ge") and isinstance(node.func.value, ast.Attribute) and node.func.value.attr == "amount":
                for a in node.args:
                    vals = []
                    if isinstance(a, ast.List): vals = a.elts
                    else: vals = [a]
                    for v in vals:
                        if isinstance(v, ast.Constant) and isinstance(v.value, str):
                            print(f"{path}:{node.lineno}: amount.{node.func.attr} with string {v.value!r}")
