cd /tmp/opencode && python3 - <<'EOF'
import os, re, difflib
base = "/app/categorizationapp/categorizationapp/BankScripts"
targets = {"PNB.py": [], "Canara.py": []}
others = {}
for f in os.listdir(base):
    if not f.endswith(".py"): continue
    lines = [l.strip() for l in open(os.path.join(base,f))]
    if f in targets: targets[f] = lines
    else: others[f] = lines

def interesting(l):
    return l.startswith("[") and ("sep_by" in l or "py_extract" in l or "remark" in l or "amount" in l)

for tf, tlines in targets.items():
    print(f"########## {tf} ##########")
    for i, l in enumerate(tlines, 1):
        if not interesting(l): continue
        best = []
        for of, olines in others.items():
            for j, ol in enumerate(olines, 1):
                if not ol.startswith("["): continue
                r = difflib.SequenceMatcher(None, l, ol).ratio()
                if r > 0.9 and l != ol:
                    best.append((r, of, j, ol))
        for r, of, j, ol in sorted(best, reverse=True)[:1]:
            print(f"{tf}:{i}: {l}")
            print(f"  ~{r:.2f} {of}:{j}: {ol}")
EOF
